'use strict';

// MODULES //

var tape = require( 'tape' );
var hasProp = require( '@stdlib/assert/has-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var Fcn = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Fcn, 'function', 'main export is a function' );
	t.end();
});

tape( 'a function instance has a `call` method', function test( t ) {
	var f = new Fcn( 'x', 'y', 'return x + y' );
	t.strictEqual( hasProp( f, 'call' ), true, 'has property' );
	t.strictEqual( isFunction( f.call ), true, 'has method' );
	t.end();
});

tape( 'the method calls a function with a given `this` value and arguments provided individually', function test( t ) {
	var f;
	var v;

	f = new Fcn( 'x', 'y', 'return x + y' );
	v = f.call( null, 1, 2 ); // eslint-disable-line no-useless-call
	t.strictEqual( v, 3, 'returns expected value' );
	t.end();
});

tape( 'the method supports providing a `this` context', function test( t ) {
	var ctx;
	var f;
	var v;

	ctx = {
		'z': 10
	};
	f = new Fcn( 'x', 'y', 'return this.z + x + y' );
	v = f.call( ctx, 1, 2 );
	t.strictEqual( v, 13, 'returns expected value' );
	t.end();
});

tape( 'the method supports calling a function with no arguments', function test( t ) {
	var f;
	var v;

	f = new Fcn( 'return 42' );
	v = f.call( null ); // eslint-disable-line no-useless-call
	t.strictEqual( v, 42, 'returns expected value' );
	t.end();
});

tape( 'the method supports calling a function with a single argument', function test( t ) {
	var f;
	var v;

	f = new Fcn( 'x', 'return x * 2' );
	v = f.call( null, 5 ); // eslint-disable-line no-useless-call
	t.strictEqual( v, 10, 'returns expected value' );
	t.end();
});
